    for m in range(2,11):
        mp={}; bad=0
        cnt=Counter()
        for r,c,v in cells: cnt[((r+c)%m,v)]+=1
        mp={k:v for (k,v),n in cnt.items()}
        mpv={k:v for k,v in cnt.items()}
        # majority per residue
        res={}
