        tot=sum(n for _,n in mpv.values())
        score=(bad/tot if tot else 1, m)
        if best is None or score<best: best=score
    _,m=best
    res={}
    cnt=Counter(((r+c)%m, v) for r,c,v in cells)
    for k in range(m):
        cand=[(v,n) for (kk,v),n in cnt.items() if kk==k]
        if cand: res[k]=max(cand,key=lambda x:x[1])[0]
    out=[row[:] for row in g]
    for r in range(h):
        for c in range(w):
            if out[r][c]==0:
